package ical

import (
	"os"
	"path/filepath"
	"sort"
	"strings"
	"testing"
	"time"
)

// TestGenerateFreeBusyMatchesSabre pins the generator against sabre
// vobject's FreeBusyGenerator output for the fb-*.ics fixtures
// (testdata/freebusy-golden.ics, regenerated by
// scripts/freebusy-golden.php). DTSTAMP and PRODID are volatile and masked.
func TestGenerateFreeBusyMatchesSabre(t *testing.T) {
	paths, err := filepath.Glob(filepath.Join("testdata", "fb-*.ics"))
	if err != nil || len(paths) == 0 {
		t.Fatalf("no fb fixtures: %v", err)
	}
	sort.Strings(paths)
	var objects [][]byte
	for _, p := range paths {
		data, err := os.ReadFile(p)
		if err != nil {
			t.Fatal(err)
		}
		objects = append(objects, data)
	}

	start := time.Date(2026, 6, 1, 0, 0, 0, 0, time.UTC)
	end := time.Date(2026, 6, 8, 0, 0, 0, 0, time.UTC)
	got, err := GenerateFreeBusy(objects, start, end, time.UTC, time.Date(2026, 7, 23, 0, 0, 0, 0, time.UTC))
	if err != nil {
		t.Fatalf("GenerateFreeBusy: %v", err)
	}

	golden, err := os.ReadFile(filepath.Join("testdata", "freebusy-golden.ics"))
	if err != nil {
		t.Fatalf("reading golden: %v", err)
	}

	gotLines, wantLines := fbLines(string(got)), fbLines(string(golden))
	if strings.Join(gotLines, "\n") != strings.Join(wantLines, "\n") {
		t.Errorf("free-busy output differs from sabre:\n--- ours ---\n%s\n--- sabre ---\n%s",
			strings.Join(gotLines, "\n"), strings.Join(wantLines, "\n"))
	}
}

// TestGenerateFreeBusyIncludesStoredVFreeBusy covers that a stored VFREEBUSY
// object contributes its FREEBUSY periods to the report (skipping FBTYPE=FREE),
// like vobject's FreeBusyGenerator — previously only VEVENTs were considered.
func TestGenerateFreeBusyIncludesStoredVFreeBusy(t *testing.T) {
	obj := []byte("BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//t//t//EN\r\n" +
		"BEGIN:VFREEBUSY\r\nUID:fb1\r\n" +
		"FREEBUSY;FBTYPE=BUSY:20260602T090000Z/20260602T100000Z\r\n" +
		"FREEBUSY;FBTYPE=FREE:20260602T120000Z/20260602T130000Z\r\n" +
		"END:VFREEBUSY\r\nEND:VCALENDAR\r\n")
	start := time.Date(2026, 6, 1, 0, 0, 0, 0, time.UTC)
	end := time.Date(2026, 6, 8, 0, 0, 0, 0, time.UTC)
	got, err := GenerateFreeBusy([][]byte{obj}, start, end, time.UTC, start)
	if err != nil {
		t.Fatalf("GenerateFreeBusy: %v", err)
	}
	out := string(got)
	if !strings.Contains(out, "FREEBUSY:20260602T090000Z/20260602T100000Z") {
		t.Errorf("stored VFREEBUSY BUSY period missing:\n%s", out)
	}
	if strings.Contains(out, "20260602T120000Z") {
		t.Errorf("FBTYPE=FREE period must be skipped:\n%s", out)
	}
}

// fbLines extracts the semantically relevant lines (VFREEBUSY content minus
// volatile DTSTAMP/PRODID).
func fbLines(s string) []string {
	var out []string
	for _, line := range strings.Split(strings.ReplaceAll(s, "\r\n", "\n"), "\n") {
		if strings.HasPrefix(line, "DTSTAMP:") || strings.HasPrefix(line, "PRODID:") || line == "" {
			continue
		}
		out = append(out, line)
	}
	return out
}

// TestGenerateFreeBusyExtraProps checks that outbox-supplied identity
// properties (UID/ORGANIZER/ATTENDEE) are injected into the VFREEBUSY, which
// CalDAVTester's postFreeBusy verifier requires to match the queried recipient.
func TestGenerateFreeBusyExtraProps(t *testing.T) {
	start := time.Date(2026, 6, 1, 0, 0, 0, 0, time.UTC)
	end := time.Date(2026, 6, 8, 0, 0, 0, 0, time.UTC)
	got, err := GenerateFreeBusy(nil, start, end, time.UTC, start,
		"UID:abc",
		"ORGANIZER;CN=User 01:mailto:user01@example.org",
		"ATTENDEE:mailto:user01@example.org")
	if err != nil {
		t.Fatalf("GenerateFreeBusy: %v", err)
	}
	for _, want := range []string{
		"UID:abc",
		"ORGANIZER;CN=User 01:mailto:user01@example.org",
		"ATTENDEE:mailto:user01@example.org",
	} {
		if !strings.Contains(string(got), want) {
			t.Errorf("VFREEBUSY missing %q:\n%s", want, got)
		}
	}
}

func TestTodoInTimeRange(t *testing.T) {
	start := time.Date(2026, 6, 1, 0, 0, 0, 0, time.UTC)
	end := time.Date(2026, 6, 8, 0, 0, 0, 0, time.UTC)
	for _, tc := range []struct {
		name  string
		lines []string
		want  bool
	}{
		{"due inside", []string{"DUE:20260603T120000Z"}, true},
		{"due before", []string{"DUE:20260501T120000Z"}, false},
		{"dtstart inside", []string{"DTSTART:20260603T120000Z"}, true},
		{"dtstart+duration straddling", []string{"DTSTART:20260530T120000Z", "DURATION:P5D"}, true},
		{"dtstart+due straddling", []string{"DTSTART:20260530T120000Z", "DUE:20260602T120000Z"}, true},
		{"completed inside", []string{"COMPLETED:20260602T120000Z"}, true},
		{"completed before", []string{"COMPLETED:20260501T120000Z"}, false},
		{"bare todo matches", nil, true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			all := append([]string{
				"BEGIN:VCALENDAR", "VERSION:2.0", "BEGIN:VTODO", "UID:t1",
				"DTSTAMP:20251201T000000Z"}, tc.lines...)
			all = append(all, "END:VTODO", "END:VCALENDAR", "")
			cal, err := Decode([]byte(strings.Join(all, "\r\n")))
			if err != nil {
				t.Fatal(err)
			}
			got, err := TodoInTimeRange(cal.Children[0], start, end, time.UTC)
			if err != nil {
				t.Fatal(err)
			}
			if got != tc.want {
				t.Errorf("TodoInTimeRange = %v, want %v", got, tc.want)
			}
		})
	}
}
